let mounted=null,oldSection=null,oldDisplay='',observer=null;
function onPage(){return location.pathname.replace(/\/$/,'')===PATH&&!!document.getElementById(PAGE)}
function getFormLink(){
 let values={};try{values=JSON.parse(sessionStorage.getItem(STORE)||'{}')||{}}catch(e){}
 const params=new URLSearchParams(location.search);
 for(const k of KEYS){if(params.get(k))values[k]=params.get(k)}
 try{sessionStorage.setItem(STORE,JSON.stringify(values))}catch(e){}
 const url=new URL(FORM);for(const k of KEYS)url.searchParams.set(k,values[k]||'');return url.href;
}
function cleanup(){
 if(observer){observer.disconnect();observer=null}
 if(mounted){mounted.remove();mounted=null}
 if(oldSection){oldSection.style.display=oldDisplay;oldSection=null;oldDisplay=''}
}
function addMotion(root){
 if(!('IntersectionObserver' in window)||window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 const elements=[...root.querySelectorAll('.workflow .section-head,.wf-card,.benefits h2,.benefit-card,.preview .section-head,.prev-item,.target .section-head,.target-card,.last h2,.last p')];
 observer=new IntersectionObserver(entries=>{
  entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('motion-in');observer.unobserve(entry.target)}});
 },{threshold:0.08,rootMargin:'0px 0px 45px 0px'});
 for(const el of elements){el.classList.add('motion-before');observer.observe(el)}
}
